impl < 'a > Id < 'a > { # [doc = " Creates an `Id` named `name`."] # [doc = ""] # [doc = " The caller must ensure that the input conforms to an"] # [doc = " identifier format: it must be a non-empty string made up of"] # [doc = " alphanumeric or underscore characters, not beginning with a"] # [doc = " digit (i.e., the regular expression `[a-zA-Z_][a-zA-Z_0-9]*`)."] # [doc = ""] # [doc = " (Note: this format is a strict subset of the `ID` format"] # [doc = " defined by the DOT language. This function may change in the"] # [doc = " future to accept a broader subset, or the entirety, of DOT's"] # [doc = " `ID` format.)"] # [doc = ""] # [doc = " Passing an invalid string (containing spaces, brackets,"] # [doc = " quotes, ...) will return an empty `Err` value."] pub fn new < Name : Into < Cow < 'a , str > > > (name : Name) -> Result < Id < 'a > , () > { let name = name . into () ; match name . chars () . next () { Some (c) if c . is_ascii_alphabetic () || c == '_' => { } _ => return Err (()) , } if ! name . chars () . all (| c | c . is_ascii_alphanumeric () || c == '_') { return Err (()) ; } Ok (Id { name }) } pub fn as_slice (& 'a self) -> & 'a str { & self . name } }